fn shoggoth_three_loss_deployment_then_drop_requires_one_region(){let mut g=setup();g.players[0].society_zone.loss_control=3;fund(&mut g,0,"JC042",3);fund(&mut g,0,"JC056",3);let id=g.core_zones[0].card.as_ref().unwrap().id.clone();act(&mut g,0,Action{card_id:Some(id),..Action::new("deploy")});while g.stack.len()>1{crate::jc029_tests::pass_top(&mut g);}g.players[0].society_zone.loss_control=2;restore(&mut g);settle(&mut g);assert_eq!(g.pending.as_ref().unwrap().choice.kind,"core-entry-region");}

pub(crate) fn shoggoth_source_bindings()->serde_json::Value{use sha2::{Digest,Sha256};let mut bindings=crate::jc066_tests::source_bindings();for(name,bytes)in[("rust-game/src/bq_commands.rs",include_bytes!("bq_commands.rs").as_slice()),("rust-game/src/msbq02.rs",include_bytes!("msbq02.rs").as_slice()),("rust-game/src/shoggoth_tests.rs",include_bytes!("shoggoth_tests.rs").as_slice()),("rust-game/src/deck.rs",include_bytes!("deck.rs").as_slice()),("rust-game/src/society.rs",include_bytes!("society.rs").as_slice()),("rust-game/src/core_zone.rs",include_bytes!("core_zone.rs").as_slice())]{bindings["files"].as_object_mut().unwrap().insert(name.into(),serde_json::json!(format!("{:x}",Sha256::digest(bytes))));}bindings}

fn entry_setup()->(Game,String){let mut g=setup();g.players[0].society_zone.loss_control=3;fund(&mut g,0,"JC042",3);fund(&mut g,0,"JC056",3);let core=g.core_zones[0].card.as_ref().unwrap().id.clone();(g,core)}
fn entry_declared_drop()->Game{let(mut g,core)=entry_setup();act(&mut g,0,Action{card_id:Some(core),..Action::new("deploy")});while g.stack.len()>1{crate::jc029_tests::pass_top(&mut g);}g.players[0].society_zone.loss_control=2;g}
fn entry_invalid(base:&Game,bad:&Game){assert!(Game::from_persisted(&serde_json::to_string(bad).unwrap()).is_err());let mut room=crate::jc029_tests::envelope(base);room.game=bad.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).is_err());}
#[test]
fn shoggoth_entry_choice_exact_count_actor_payload_and_paid_frame_survive(){let mut g=entry_declared_drop();settle(&mut g);let p=g.pending.clone().unwrap();let frame=g.stack.last().unwrap().frame.clone().unwrap();let money=g.resources(0);assert_eq!(p.choice.min,Some(1));assert_eq!(p.choice.max,Some(1));assert_eq!(p.choice.allow_decline,Some(false));let good=Action{choice_id:Some(p.choice.id.clone()),selected:Some(vec![p.choice.options[0].id.clone()]),..Action::new("choose")};
 reject(&mut g,1,good.clone());for selected in [vec![],vec![p.choice.options[0].id.clone(),p.choice.options[0].id.clone()],p.choice.options.iter().take(2).map(|o|o.id.clone()).collect(),vec!["region:99".into()]]{reject(&mut g,0,Action{selected:Some(selected),..good.clone()});}reject(&mut g,0,Action{region:Some(0),..good.clone()});restore(&mut g);assert_eq!(serde_json::to_value(&frame).unwrap(),serde_json::to_value(g.stack.last().unwrap().frame.as_ref().unwrap()).unwrap());act(&mut g,0,good.clone());assert_eq!(g.resources(0),money);assert!(g.regions[0].cards.iter().any(|c|c.definition=="BQ046"));reject(&mut g,0,good);restore(&mut g);}
#[test]
fn shoggoth_entry_choice_corruption_and_region_identity_rejected(){let mut g=entry_declared_drop();settle(&mut g);for n in 0..8{let mut x=g.clone();match n{0=>x.pending.as_mut().unwrap().choice.min=Some(0),1=>x.pending.as_mut().unwrap().choice.max=Some(2),2=>x.pending.as_mut().unwrap().seat=1,3=>{x.stack.pop();},4=>{let i=x.stack.last().unwrap().clone();x.stack.push(i);},5=>{let c=x.make_card("DQJC115",0);x.regions[0].card=c;},6=>{let f=x.stack.last().unwrap().frame.clone().unwrap();x.effects.push_back(Effect::Frame{frame:Box::new(f)});},_=>x.pending.as_mut().unwrap().resolution=ChoiceResolution::Forecast{draw:false}}entry_invalid(&g,&x);}restore(&mut g);}
#[test]
fn shoggoth_entry_chaos_stays_random_and_no_eligible_region_cancels_paid_entry(){let(mut g,core)=entry_setup();reject(&mut g,0,Action{card_id:Some(core.clone()),region:Some(0),..Action::new("deploy")});act(&mut g,0,Action{card_id:Some(core),..Action::new("deploy")});settle(&mut g);assert!(g.pending.is_none());assert_eq!(g.regions.iter().flat_map(|r|&r.cards).filter(|c|c.definition=="BQ046").count(),1);restore(&mut g);
 let mut g=entry_declared_drop();g.world.clear();for r in &mut g.regions{r.vacant=true;}settle(&mut g);assert!(g.pending.is_none());assert!(g.players[0].graveyard.iter().any(|c|c.definition=="BQ046"));assert_eq!(g.resources(0),3);restore(&mut g);
 let mut g=entry_declared_drop();settle(&mut g);g.eliminate(0);assert!(g.pending.is_none());assert!(!g.stack.iter().any(|i|i.controller==0));restore(&mut g);}
fn entry_duplicate(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();if s["command"]["action"]["kind"]=="beginResponse"{assert_eq!(d.outcome,"accepted");let mut after=crate::room::RoomEnvelope::from_persisted(&d.state).unwrap();assert_eq!(after.revision,r.revision+1);assert_eq!(after.game.version,after.revision);after.game.version=r.game.version;assert!(serde_json::to_value(&after.game).unwrap()==serde_json::to_value(&r.game).unwrap(),"BeginResponse duplicate changed gameplay beyond its synchronized revision");}else{assert!(!d.changed&&d.journal.is_empty(),"duplicate {:?}",s["command"]);assert_eq!(d.state,s["expected"]["state"]);}s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn entry_response_trace()->serde_json::Value{use crate::abi112_review_play_tests::Trace;let(mut g,core)=entry_setup();let warden=field(&mut g,"BQ053",0);fund(&mut g,2,"JC104",2);let spell=held(&mut g,"JC102",2);let mut t=Trace::new_preserving_rng(g,"msbq02-prepared-real-warden-response".into(),5201);t.action(0,Action{card_id:Some(core),..Action::new("deploy")});while t.room.game.stack.len()>1{t.pass();}let mut removed=false;let mut picked=false;
 for _ in 0..100{if let Some(p)=t.room.game.pending.clone(){if p.choice.kind=="core-entry-region"{t.choose(vec![p.choice.options.last().unwrap().id.clone()]);picked=true;}else if p.choice.options.iter().any(|o|o.id=="accept"){t.choose(vec!["accept".into()]);}else{t.choose(p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());}continue;}if picked&&t.room.game.stack.is_empty(){break;}if !removed&&t.room.game.legal_actions(2).iter().any(|a|a.action.kind=="play"&&a.action.card_id.as_deref()==Some(&spell)&&a.action.target_id.as_deref()==Some(&warden)){let w=t.room.pacing.window.clone().unwrap();t.step(2,crate::room::SessionAction::BeginResponse{window_id:w.id.clone(),intent_id:"warden-removal".into()});t.step(2,crate::room::SessionAction::SubmitResponse{window_id:w.id,intent_id:"warden-removal".into(),action:Action{card_id:Some(spell.clone()),target_id:Some(warden.clone()),..Action::new("play")}});removed=true;}else{t.pass();}}
 assert!(removed&&picked);assert_eq!(t.room.game.players[0].society_zone.loss_control,2);assert!(t.room.game.regions.last().unwrap().cards.iter().any(|c|c.definition=="BQ046"));entry_duplicate(t.value())}
#[test]
fn shoggoth_entry_real_response_commands_export(){let cases=vec![entry_response_trace(),entry_natural_trace()];if let Ok(path)=std::env::var("MSBQ02_ENTRY_NATIVE_OUT"){let mut bindings=shoggoth_source_bindings();use sha2::{Digest,Sha256};bindings["files"]["rust-game/src/core_entry.rs"]=serde_json::json!(format!("{:x}",Sha256::digest(include_bytes!("core_entry.rs"))));std::fs::write(path,serde_json::to_vec_pretty(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":bindings,"cases":cases})).unwrap()).unwrap();}}
fn entry_natural_trace()->serde_json::Value{
 use crate::abi112_review_play_tests::Trace;let(seed,g)=(1..4097).find_map(|seed|{let g=natural(seed);let count=|id:&str|g.players[0].hand.iter().filter(|c|c.definition==id).count();(count("BQ051")>0&&count("BQ064")>0&&(count("BQ048")>0||count("BQ051")>1)).then_some((seed,g))}).expect("bounded real natural hand");
 let mut t=Trace::new_preserving_rng(g,"msbq02-natural-three-loss-core-entry".into(),5202);let mut cleared=false;let mut deployed=false;
 for _ in 0..900{if let Some(p)=t.room.game.pending.clone(){let mut ids=p.choice.options.iter().map(|o|o.id.clone()).collect::<Vec<_>>();if p.seat==0{ids.sort_by_key(|id|t.room.game.players[0].hand.iter().find(|c|c.id==*id).map_or(0,|c|usize::from(["BQ051","BQ064","BQ048"].contains(&c.definition.as_str()))));}ids.truncate(p.choice.min.unwrap_or(0));t.choose(ids);continue;}if deployed&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}
 let g=&t.room.game;let legal=g.legal_actions(0);let wanted=if g.players[0].assets.len()<5{let gray=g.players[0].assets.iter().any(|c|catalog::card(&c.definition).color=="灰");let red=g.players[0].assets.iter().any(|c|catalog::card(&c.definition).color=="红");legal.iter().find(|a|a.action.kind=="asset"&&g.players[0].hand.iter().find(|c|Some(&c.id)==a.action.card_id.as_ref()).is_some_and(|c|if !gray{c.definition=="BQ064"}else if !red{c.definition=="BQ048"||c.definition=="BQ051"&&g.players[0].hand.iter().filter(|h|h.definition=="BQ051").count()>1}else{c.definition=="JC125"}))}else if !cleared{legal.iter().find(|a|a.action.kind=="play"&&g.players[0].hand.iter().any(|c|c.definition=="BQ051"&&Some(&c.id)==a.action.card_id.as_ref()))}else if !deployed&&g.players[0].society_zone.loss_control==3{legal.iter().find(|a|a.action.kind=="deploy"&&a.action.region.is_none()&&g.core_zones[0].card.as_ref().is_some_and(|c|Some(&c.id)==a.action.card_id.as_ref()))}else{None};
 if let Some(a)=wanted{if a.action.kind=="play"{cleared=true;}if a.action.kind=="deploy"{deployed=true;}t.action(0,a.action.clone());}else{t.pass();}}
 assert!(cleared&&deployed&&t.room.game.stack.is_empty());assert_eq!(t.room.game.players[0].society_zone.loss_control,3);assert_eq!(t.room.game.regions.iter().flat_map(|r|&r.cards).filter(|c|c.definition=="BQ046").count(),1);let mut v=t.value();v["construction"]=serde_json::json!({"seed":seed,"deck":draft(),"ordinaryCount":50,"coreCount":1,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true});entry_duplicate(v)
}
